insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('headlight-housings-r32','bub','headlight-housings','Headlight housings: remove, replace, restore','Exterior',null,array['headlight housing','fogged headlight','hazy lens','restoration','bi-xenon upgrade','bumper cover']::text[],true,'1.5–2 hr',2) on conflict (id) do update set title=excluded.title, category=excluded.category, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('headlights',$j${"id": "headlights", "title": "Headlight bulbs", "fits": "2006–2009 VW GTI (FSI & TSI) · 2008 VW R32", "heroId": "headlight-hero", "alsoFits": "2006–09 GTI (halogen and bi-xenon); Golf/Rabbit and Jetta share the technique, not the housings", "category": "Electrical", "kind": "repair", "variants": {"question": "Which headlights does your car have?", "hint": "US Mk5 GTIs came both ways. Bi-xenon housings have a projector with a bluish-white beam and a small inner halogen; halogen housings use two ordinary reflector bulbs.", "options": [{"id": "halogen", "label": "Halogen", "when": "H7 bulbs, yellow-white light, cheap to replace"}, {"id": "xenon", "label": "Bi-xenon (HID)", "when": "One D2S bulb does low and high via a shutter; ~$50 each"}]}, "glance": {"timeFirst": "20 min in place · 1 hr with the housing out", "timeRepeat": "30 min", "difficulty": 2, "cost": "$20–40 halogen · $80–120 xenon pair · $300+ per housing", "risk": "HID ballast voltage · scratching the bumper · touching halogen glass", "why": "Bulbs dim before they die, and one dead low beam is a ticket. Halogen or bi-xenon, the swap itself is minutes; on this car the access is the job, and the housing guide (in Exterior) covers getting it out.", "note": "Pelican and the forums agree: possible in place on the passenger side with small hands, painful on the driver's side, easy with the housing out."}, "heroCap": "Bulb caps are on the back of the housing. On this car the honest way to reach them is with the housing out; see the housing guide for that part, or try the passenger-side shortcut.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Halogen H7 low beams: typically 1–3 years of nightly use", "only": ["halogen"]}, {"text": "D2S xenon bulbs: typically 5–8 years; they dim and shift colour rather than fail suddenly", "only": ["xenon"]}], "earliest": "Cheap 'blue' halogens can go in months", "detail": "Halogens burn out; xenons fade toward purple and lose output long before they quit. Replace xenons in pairs so the colours match, and because the second one is close behind. Housings themselves go hazy from UV on the outside (polish) or from a failed seal on the inside (replace).", "factors": ["Daytime running lights on all the time", "Vibration from a rough road", "Touching halogen glass on install"], "inspect": ["Look at your low beams on a garage wall once a year: colour match and pattern"], "confidence": {"level": "community", "n": 3, "note": "Owner experience; no factory interval."}}, "should": {"yesIf": ["Low beam out, or the dash says 'dipped beam'", "Beams noticeably different colours (xenon)", "You're replacing a housing anyway"], "codes": [], "notes": [{"text": "H7 for the low beam. Most Mk5 GTI halogen housings also use H7 for the high beam, but confirm by reading the old bulb's base before you buy. Any decent brand (Osram, Philips) beats a blue-tinted 'upgrade' bulb, which is dimmer and short-lived.", "only": ["halogen"]}, {"text": "The outer projector's single D2S bulb does both low and high beam; a shutter moves for high. The small inner lamp is an H7 'flash to pass' that some owners code to act as an extra high beam. When the dash complains about the low beam, it's the D2S. Buy a name brand (Philips, Osram) and replace both sides.", "only": ["xenon"]}, {"text": "The ballast makes several thousand volts to light a D2S. Battery disconnected, lights off, and never operate a ballast with the bulb out.", "only": ["xenon"]}, "LED 'H7 replacement' bulbs in halogen reflector housings scatter light and blind other drivers; most aren't legal for road use. A better halogen is the honest upgrade for a reflector; a housing swap to bi-xenon is the real one."], "confidence": {"level": "medium", "n": 3, "note": "Pelican article and forum threads; bulb-type detail confirmed for xenon, halogen high beam noted as 'confirm on the old bulb'."}}, "parts": [{"tier": "oe", "name": "H7 halogen bulbs (pair)", "pn": "Osram Night Breaker / Philips X-tremeVision", "note": "Replace in pairs", "price": "$20–40", "links": [], "only": ["halogen"]}, {"tier": "oe", "name": "D2S xenon bulbs (pair)", "pn": "Philips 85122 / Osram 66240", "note": "Replace in pairs; name brand only", "price": "$80–120", "links": [], "only": ["xenon"]}], "aftermarket": [{"name": "Osram Night Breaker / Philips X-treme H7", "note": "Brighter, whiter halogens that are still legal. Shorter life than standard.", "price": "$25–40 / pair", "signal": "Best legal halogen", "links": [], "only": ["halogen"]}], "tools": [{"name": "Nitrile gloves (halogen glass), flashlight"}, {"name": "If the housing comes out: see the housing guide's tools"}], "before": ["Battery negative disconnected, especially for xenon.", "Don't touch halogen glass with bare fingers; the oil creates a hot spot and the bulb fails early. If you did, wipe it with alcohol.", "Lay a blanket on the fender edge; you'll rest the housing there."], "steps": [{"n": 1, "title": "Try the shortcut (passenger side, halogen)", "only": ["halogen"], "blocks": [{"t": "text", "b": "With the airbox snorkel out of the way, small hands can reach the low-beam cap on the passenger side from above: twist the round cap off, unplug the bulb, release its wire clip, swap it. If you can do both sides this way, you're done in twenty minutes. Most people can't reach the driver's side past the fuse box and battery; for that side, continue."}]}, {"n": 2, "title": "Get the housing out", "blocks": [{"t": "text", "b": "Follow the headlight housing guide (Exterior) to loosen the bumper cover's top edge and unscrew the housing. Battery negative disconnected first, especially on xenon cars."}, {"t": "ill", "id": "headlight-hero", "cap": "The bulb caps are only reachable once the housing is out on the blanket."}, {"t": "warn", "b": "Xenon: the ballast is on the housing and makes thousands of volts. Battery off, and never power a ballast without a bulb.", "only": ["xenon"]}]}, {"n": 3, "title": "Swap the bulbs", "blocks": [{"t": "text", "b": "Round caps on the back: twist off. Low beam H7: unplug, squeeze the wire retainer clip, lift the bulb out, new one in with the tab orientation matching, clip, plug, cap. High beam: same. Gloves on the glass.", "only": ["halogen"]}, {"t": "text", "b": "Remove the projector's rear cap, unplug the igniter connector from the D2S, release the bulb's retaining ring or clip, lift the bulb straight out without touching the glass, seat the new one in the same orientation, retainer, igniter, cap. Do the other side too; colours must match.", "only": ["xenon"]}]}, {"n": 4, "title": "Housing back in, aim check", "blocks": [{"t": "text", "b": "Housing back in per the housing guide, battery on. Park 25 feet from a wall: low-beam cutoffs level with each other and just below headlight height. Adjusters are on the back of the housing."}]}], "alsoReplace": [{"name": "Turn signal and DRL bulbs", "why": "Same housing, same trip."}, {"name": "Lens restoration", "why": "Housing on a bench is when to polish and UV-coat it; see the housing guide."}], "check": {"tab": "Bulb?", "title": "Bulb or something else?", "illId": "headlight-hero", "illCap": "Colour, moisture and the dash message narrow it quickly.", "rows": [{"see": "One low beam out, dash message", "means": "Bulb (D2S on xenon, H7 on halogen).", "do": "Replace, in pairs."}, {"see": "Beam flickers or takes several tries to light (xenon)", "means": "Bulb at end of life, or the ballast/igniter.", "do": "New bulbs first; if it persists, ballast."}], "c": {"level": "community", "n": 3, "note": "Owner threads and vendor guidance."}}, "aftercare": ["Check aim after a week.", "Xenon colour mismatch that persists: the ballasts differ or one bulb is a different brand."], "disagreements": [{"topic": "Can you do it in place?", "pos": "Some owners manage the passenger side; Pelican says take the assembly out.", "call": "Try the shortcut on the passenger side; take it out for the driver's side and for any xenon."}, {"topic": "Halogen high-beam bulb type", "pos": "H7 on most; not confirmed from a factory table.", "call": "Read the old bulb."}, {"topic": "LED drop-ins", "pos": "Popular; cheap.", "call": "Not in a reflector housing. Glare, and not legal on the road."}], "sources": ["Pelican Parts Mk5 GTI headlight bulb and assembly article", "VWVortex 'GTI Headlight Bulb Replacement' (bi-xenon detail)", "Owner threads on in-place bulb access", "Bulb and housing listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('headlight-housings',$j${"id": "headlight-housings", "title": "Headlight housings: remove, replace, restore", "fits": "2006–2009 VW GTI (FSI & TSI) · 2008 VW R32", "heroId": "headlight-hero", "alsoFits": "2006–09 GTI and 2008 R32 (same housings by trim: halogen or bi-xenon)", "category": "Exterior", "kind": "repair", "variants": {"question": "What are you doing to the housing?", "hint": "Same removal either way. Replacement includes upgrading a halogen car to bi-xenon housings.", "options": [{"id": "replace", "label": "Replace the housing", "when": "Fogged inside, cracked, or upgrading to bi-xenon"}, {"id": "restore", "label": "Restore the lens", "when": "Hazy outside; polish and UV-coat with the housing on the bench"}]}, "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$300–900 per housing · $25 restoration kit", "risk": "Scratching the bumper cover · xenon ballast voltage · aim afterwards", "why": "Mk5 housings go hazy on the outside from UV and foggy on the inside when a seal fails; the first is a bench polish, the second is a new housing. Either way the housing has to come out, and on this car that means loosening the bumper cover's top edge. It sounds worse than it is.", "note": "Pelican's Mk5 GTI headlight article is the reference; owner threads agree that removing the cover fully is faster than fighting a loosened one."}, "heroCap": "Housing screws hide behind the bumper cover's top edge. Loosen the cover, unscrew the housing, pull it forward.", "lifespan": {"title": "When to expect it", "headline": ["Outside haze by 10 years; inside fogging when a seal or vent fails"], "earliest": null, "detail": "Polycarbonate lenses lose their UV coat and yellow. Moisture inside after a wash or rain means a failed seal, a missing vent cap or a cracked housing, and that's replacement or a careful reseal.", "factors": ["Sun exposure", "Pressure washing at the seams", "Age of the seal"], "inspect": ["Look at the lenses in daylight once a year; check for condensation after a wash"], "confidence": {"level": "community", "n": 3, "note": "Owner experience."}}, "should": {"yesIf": ["Fog inside the lens", "Cracked lens or broken mounting tab", "Yellow, hazy lens that dims the beam", "Upgrading halogen to bi-xenon"], "codes": [], "notes": [{"text": "Upgrading a halogen car to bi-xenon housings is the proper headlight upgrade, but it's more than two housings: ballasts and igniters, the xenon wiring or a harness, and ideally the auto-levelling module and sensors to be legal and not blind people. Budget for the system, not the housings.", "only": ["replace"]}, {"text": "Restoration works on outside haze only. If the fog is inside, no amount of polishing helps.", "only": ["restore"]}, "Xenon cars: the ballast is on the housing. Battery negative off before you unplug anything."], "confidence": {"level": "medium", "n": 3, "note": "Pelican article and owner threads."}}, "parts": [{"tier": "oe", "name": "Headlight housing (each)", "pn": "halogen or bi-xenon by VIN", "note": "OE (Hella) or OE-supplier", "price": "$300–900", "links": [], "only": ["replace"]}, {"tier": "oe", "name": "Bumper cover clips and screws", "pn": "a few break every time", "note": "", "price": "$10", "links": []}, {"tier": "aftermarket", "name": "Headlight restoration kit with UV clear coat", "pn": "e.g. Cerakote, Sylvania", "note": "Kits without a UV coat haze again in months", "price": "$20–30", "links": [], "only": ["restore"]}], "aftermarket": [{"name": "OEM-style bi-xenon housings (Hella)", "note": "Projector beam, proper cutoff, legal. Needs the ballasts, wiring and levelling to do it right.", "price": "$700–1,200 / pair", "signal": "The proper upgrade", "links": [], "only": ["replace"]}, {"name": "Depo / TYC replacement housings", "note": "Budget replacements for a fogged or cracked lens. Fit varies; beam quality fine for halogen, hit-and-miss for projectors.", "price": "$150–300 each", "signal": "Budget lens fix", "links": [], "only": ["replace"]}, {"name": "Cerakote headlight restoration kit", "note": "Sanding pads plus a real ceramic UV coat; the one that lasts.", "price": "$20–30", "signal": "Best restoration kit", "links": [], "only": ["restore"]}], "tools": [{"name": "T25 and T30 Torx, 10mm socket, trim tool for bumper clips"}, {"name": "Soft blanket for the fender edge; masking tape for the paint around the lens", "only": ["restore"]}, {"name": "A friend to hold the bumper corner"}], "before": ["Battery negative disconnected on xenon cars.", "Lay a blanket on the fender edge; the housing rests there.", "Photograph the connectors before unplugging."], "steps": [{"n": 1, "title": "Loosen the bumper cover's top edge", "blocks": [{"t": "text", "b": "Behind the grille and along the top of the bumper cover: Torx screws into the radiator support (T25/T30) and clips. Remove the screws along the top and the ones in the wheel-arch liner at the bumper corner (T25) so the corner of the cover can be pulled forward a few inches. Pelican's advice is to remove the cover entirely; it's another fifteen minutes and saves scratching it."}, {"t": "ill", "id": "headlight-hero", "cap": "The housing screws are behind the bumper cover's edge."}]}, {"n": 2, "title": "Housing out", "blocks": [{"t": "text", "b": "With the cover pulled forward, the housing screws are visible (top edge and outer side). Remove them, unplug the main connector on the back, and slide the housing forward and out onto the blanket."}, {"t": "warn", "b": "Xenon: don't unplug or plug anything with the lights on, and don't power a ballast without a bulb."}]}, {"n": 3, "title": "Swap bulbs and parts across", "only": ["replace"], "blocks": [{"t": "text", "b": "Move the bulbs (and on xenon cars the ballast, if the new housing comes without) to the new housing; see the bulbs guide for handling. Check the new housing's mounting tabs and adjusters against the old before you fit it."}]}, {"n": 3, "title": "Restore the lens", "only": ["restore"], "blocks": [{"t": "text", "b": "Tape the surrounding paint. Wet-sand in the kit's grit sequence until the yellow is gone and the haze is uniform, then finer, then the kit's polish. Clean with alcohol and apply the UV clear coat in one even pass. Let it cure per the kit before it sees water."}, {"t": "note", "b": "Skipping the UV coat is why 'headlight restorer' has a bad name. The coat is the product; the sanding is just prep."}]}, {"n": 4, "title": "Housing in, cover on", "blocks": [{"t": "text", "b": "Plug the housing in, slide it onto its locating pins, screws in. Bumper corner back, screws and clips (replace the broken ones). Battery negative on."}]}, {"n": 5, "title": "Aim", "blocks": [{"t": "text", "b": "Park 25 feet from a wall on level ground. Low-beam cutoffs level with each other and just below headlight height; adjusters on the back of the housing. Xenon cars with auto-levelling: turn the car on and watch the beams settle; one staying low means the level-sensor arm is disconnected."}]}], "alsoReplace": [{"name": "Bulbs", "why": "Housing is out; replace low beams in pairs while you're here (bulbs guide)."}, {"name": "Headlight washer nozzle and level sensor check", "why": "Xenon cars: with the bumper corner loose, check the washer hose and that the level-sensor arm is attached."}, {"name": "Fog light bulbs", "why": "Bumper corner is loose; the fog lights are right there."}], "check": {"tab": "Replace or restore?", "title": "Replace or restore?", "illId": "headlight-hero", "illCap": "Inside or outside is the whole question.", "rows": [{"see": "Yellow, hazy, beam dim", "means": "UV haze on the outside.", "do": "Restore with a UV-coat kit."}, {"see": "Fog or drops inside the lens", "means": "Seal or vent failed.", "do": "Housing, or a careful reseal."}, {"see": "Cracked lens or broken tab", "means": "Done.", "do": "Housing."}], "c": {"level": "community", "n": 3, "note": "Owner threads."}}, "aftercare": ["Check aim after a week.", "Restored lenses: no pressure washer at the lens for a month."], "disagreements": [{"topic": "Loosen the cover or remove it?", "pos": "Loosening saves time; removing saves paint.", "call": "Remove it if you're new to this."}, {"topic": "Halogen-to-xenon upgrade", "pos": "Housings alone vs the whole system.", "call": "Whole system, or don't."}], "sources": ["Pelican Parts Mk5 GTI headlight bulb and assembly article", "Owner threads on housing removal and restoration", "Housing and restoration kit listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
